// === Tab: mySketch ===
/**
Baily's beads is a phenomena which can be seen during a solar eclipse.
**/


var shaderCanvas, theShader;

const MAX_POSITIONS = 50;
var imgTexture;
let mat = [
  1, 0, 0,  // column 1
  0, 1, 0,  // column 2
  0, 0, 1   // column 3
];

var numStars = 100;

createOPC();
/**
Defines: 
1. Halo: u_halo_radius, u_off_center
*/

function preload(){
	shaderCanvas = createGraphics(512, 512, WEBGL);
	let gl = shaderCanvas._renderer.GL;
	gl.enable(gl.BLEND);
	gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);

	theShader = new p5.Shader(shaderCanvas.renderer, vertShader, fragShader);
}

function setup() {
	createCanvas(shaderCanvas.width, shaderCanvas.height);
	imgTexture = loadImage('https://openprocessing.org/sketch/2669162/files/earth_night.jpg');

	let axis = createVector(-0.2,1,+0.1).normalize();
	let dir = createVector(-1,0,3);
	let dir2 = axis.cross(dir).normalize();
	dir = dir2.cross(axis).normalize();
	// x is left\right
	// y is up\down axis
	// z is out\in	
	mat = [
		dir.x, axis.x, dir2.x,
		dir.y, axis.y, dir2.y,
		dir.z, axis.z, dir2.z,
	]

	background(0);
	genBeads();
	genBeadsUniforms();
	setUniforms();
	//noLoop();   // I hate everything
	//redraw();	
}

var positions = [];
var radius = [];
var beads = [];

function genBeads(){
	beads = [];
	for (let i=0; i<MAX_POSITIONS; i++){
		let x = random();
		x = x*x;		
		beads.push([random([-1,1])*x, (1-x)*(1-x)*0.35]);
	}	
}

function updateBeads(){
	var newBeads = [];
	for (let bead of beads){
		bead[1] *= random([1.001, 1/1.001]);
	}
	genBeadsUniforms();
}

function genBeadsUniforms(){
	positions = [];
	radius = [];
	for (let bead of beads){
		var x = bead[0];
		let r = bead[1];
		var angle = Math.PI/4 + x*Math.PI/3;
		positions.push(cos(angle));
		positions.push(sin(angle));
		radius.push(random(r*0.9, r*1.1,));
	}
}


function setUniforms(){
	// Screen uniforms
	theShader.setUniform("u_resolution", [shaderCanvas.width, shaderCanvas.height]);
	theShader.setUniform("u_density", shaderCanvas.pixelDensity());

	// Beads uniforms
	theShader.setUniform("u_positions", positions);
	theShader.setUniform("u_radius", radius);

	// Halo uniforms
	theShader.setUniform("u_halo_radius", u_halo_radius);
	theShader.setUniform("u_off_center", u_off_center);

	// Earth uniform
	theShader.setUniform("u_texture", imgTexture);
	theShader.setUniform('u_orientation', mat);

}

function draw() {
	//updateBeads();

	shaderCanvas.clear();		
	setUniforms();
	shaderCanvas.shader(theShader);
	shaderCanvas.rect(0,0,width,height);
	image(shaderCanvas,0,0);
}

function createOPC(){
	//OPC.slider(variableName, defaultValue, [min], [max], [step]);
	OPC.slider('u_halo_radius',   0.9, 0, 1.2, 0.01);
	OPC.slider('u_off_center', 0.08, 0, 0.3, 0.01);
	OPC.button('beadsButton', 'Randomize Beads');
	OPC.button('saveButton', 'Save image');
}

var  imageIndex = 0;
function buttonPressed(variableName, value) {
	if (variableName === 'saveButton') {
		saveCanvas(shaderCanvas,`baily_beads_${imageIndex}`,'png');
		imageIndex++;
	}
	if (variableName === 'beadsButton') {
		genBeads();
		genBeadsUniforms();
		redraw();
	}
}

// === Tab: vert ===
let vertShader = `

#ifdef GL_ES //for browser or mobile
//can change mediump to either lowp or highp.
precision mediump float;
#endif

// Input:
attribute vec3 aPosition;  //position of the vertex

void main() {
  vec4 positionVec4 = vec4(aPosition, 1.0);

	// This is a weird behaviour in p5. Need to scale the vertices so they will appear in the right place.
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

	//Output:
  gl_Position = positionVec4;
}`;


// === Tab: frag ===
let fragShader = `
#ifdef GL_ES 
precision mediump float;
#endif

const float PI = 3.141592653589793;

uniform vec2 u_resolution;
uniform float u_density;
uniform vec2 u_positions[${MAX_POSITIONS}];
uniform float u_radius[${MAX_POSITIONS}];
uniform float u_time;
uniform sampler2D u_texture;
uniform mat3 u_orientation;


uniform float u_halo_radius;
uniform float u_off_center;


// ============================== Scene ==============================


void main() {		
	vec2 uv = 2.*(gl_FragCoord.xy/u_density-u_resolution/2.)/u_resolution.y;
	uv *= 1.2;
	//coordinates are now in [-1.2,1.2] x [-1.2,1.2]

	float haloDist = 1. - length(uv-vec2(u_off_center))/u_halo_radius; // 1= center, 0=on radius
	float halo=pow(1.+haloDist,16.) * step(1., length(uv));

	float beads = 0.;
	float dist;
	for (int i=0; i<${MAX_POSITIONS}; i++){
		dist = max(1.-distance(u_positions[i], uv)/u_radius[i], 0.);		
		beads += pow(dist, 16.);
	}	

	vec3 color = vec3(0.);
	float r2 = dot(uv,uv);
	if (r2<=1.){
		float z =sqrt(1.-r2);
		vec3 pos = u_orientation * vec3(uv,z);

		float theta = 0.5+atan(pos.z, pos.x)/(2.*PI);
		float phi = 0.5-asin(pos.y)/PI;
		color = texture2D(u_texture, vec2(theta, phi)).rgb;
	}

	color += vec3(halo) + vec3(1.0, 0.9, 0.7)*beads;
	gl_FragColor = vec4(color, 1.);


}

`

